@using sv_78646f161843475bb21c45da870eb5cc.Models
@inject IProductService ProductService
@rendermode InteractiveServer

<PageTitle>Product Catalog</PageTitle>

<h1 class="mb-4">Product Catalog</h1>

<div class="catalog-container d-flex">
    @* ───── Left sidebar ───── *@
    <aside class="catalog-sidebar">
        <h5>Filters</h5>

        @* Category checkboxes *@
        <div class="mb-3">
            <label class="form-label fw-semibold">Category</label>
            @if (categories is not null)
            {
                @foreach (var cat in categories)
                {
                    <div class="form-check">
                        <input class="form-check-input" type="checkbox" id="cat-@cat"
                               checked="@selectedCategories.Contains(cat)"
                               @onchange="e => ToggleCategory(cat, (bool)e.Value!)" />
                        <label class="form-check-label" for="cat-@cat">@cat</label>
                    </div>
                }
            }
        </div>

        @* Price range *@
        <div class="mb-3">
            <label class="form-label fw-semibold">Price Range</label>
            <div class="d-flex gap-2">
                <input type="number" class="form-control" placeholder="Min" @bind="minPrice" min="0" />
                <input type="number" class="form-control" placeholder="Max" @bind="maxPrice" min="0" />
            </div>
        </div>

        @* In-stock toggle *@
        <div class="form-check mb-3">
            <input class="form-check-input" type="checkbox" id="inStockOnly" @bind="inStockOnly" />
            <label class="form-check-label" for="inStockOnly">In Stock Only</label>
        </div>

        <div class="d-grid gap-2">
            <button class="btn btn-primary" @onclick="ApplyFilters">Apply Filters</button>
            <button class="btn btn-outline-secondary" @onclick="ClearFilters">Clear Filters</button>
        </div>
    </aside>

    @* ───── Main content ───── *@
    <main class="catalog-main">
        @if (isLoading)
        {
            <div class="d-flex justify-content-center align-items-center py-5">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else if (errorMessage is not null)
        {
            <div class="alert alert-danger" role="alert">
                <strong>Error:</strong> @errorMessage
            </div>
        }
        else if (result is null || result.Items.Count == 0)
        {
            <div class="alert alert-info" role="alert">
                No products found. Try adjusting your filters.
            </div>
        }
        else
        {
            @* Toolbar *@
            <div class="d-flex justify-content-between align-items-center mb-3 flex-wrap gap-2">
                <div>
                    <label class="form-label me-2 mb-0" for="sortSelect">Sort by:</label>
                    <select id="sortSelect" class="form-select d-inline-block w-auto" @bind="sortBy" @bind:after="OnSortChanged">
                        <option value="price_asc">Price: Low to High</option>
                        <option value="price_desc">Price: High to Low</option>
                        <option value="name_asc">Name: A-Z</option>
                        <option value="rating_desc">Rating: Highest</option>
                    </select>
                </div>
                <span class="text-muted">
                    Showing @(StartItem)–@(EndItem) of @result.TotalCount products
                </span>
            </div>

            @* Product grid *@
            <div class="product-grid">
                @foreach (var product in result.Items)
                {
                    <div class="card product-card" @onclick="() => OnProductSelected(product)" role="button" tabindex="0">
                        <div class="product-image-placeholder d-flex align-items-center justify-content-center">
                            <span class="text-muted small text-center px-2">@product.Name</span>
                        </div>
                        <div class="card-body">
                            <h6 class="card-title text-truncate" title="@product.Name">@product.Name</h6>
                            <p class="card-text fw-bold mb-1">@product.Price.ToString("C")</p>
                            <div class="mb-1" title="@($"{product.Rating:F1} out of 5")">@RenderStars(product.Rating)</div>
                            @if (!product.InStock)
                            {
                                <span class="badge bg-danger mb-2">Out of Stock</span>
                            }
                            <button class="btn btn-sm btn-success w-100"
                                    disabled="@(!product.InStock)"
                                    @onclick="() => { }" @onclick:stopPropagation="true">
                                Add to Cart
                            </button>
                        </div>
                    </div>
                }
            </div>

            @* Pagination *@
            <nav aria-label="Product pagination" class="mt-4">
                <ul class="pagination justify-content-center flex-wrap">
                    <li class="page-item @(currentPage == 1 ? "disabled" : "")">
                        <button class="page-link" @onclick="() => GoToPage(currentPage - 1)" disabled="@(currentPage == 1)">Previous</button>
                    </li>
                    @for (int i = 1; i <= TotalPages; i++)
                    {
                        var pageNum = i;
                        <li class="page-item @(pageNum == currentPage ? "active" : "")">
                            <button class="page-link" @onclick="() => GoToPage(pageNum)">@pageNum</button>
                        </li>
                    }
                    <li class="page-item @(currentPage >= TotalPages ? "disabled" : "")">
                        <button class="page-link" @onclick="() => GoToPage(currentPage + 1)" disabled="@(currentPage >= TotalPages)">Next</button>
                    </li>
                </ul>
            </nav>
        }
    </main>
</div>

@code {
    [Parameter] public EventCallback<Product> OnProductClicked { get; set; }

    private const int PageSize = 12;

    // Filter state
    private List<string>? categories;
    private HashSet<string> selectedCategories = new();
    private decimal? minPrice;
    private decimal? maxPrice;
    private bool inStockOnly;

    // Search state
    private string sortBy = "price_asc";
    private int currentPage = 1;
    private PagedResult<Product>? result;
    private bool isLoading;
    private string? errorMessage;

    private int TotalPages => result is null || result.TotalCount == 0
        ? 1
        : (int)Math.Ceiling((double)result.TotalCount / PageSize);

    private int StartItem => result is null || result.Items.Count == 0
        ? 0
        : (result.Page - 1) * PageSize + 1;

    private int EndItem => result is null
        ? 0
        : (result.Page - 1) * PageSize + result.Items.Count;

    protected override async Task OnInitializedAsync()
    {
        await LoadCategoriesAsync();
        await SearchAsync();
    }

    private async Task LoadCategoriesAsync()
    {
        try
        {
            categories = await ProductService.GetCategoriesAsync();
        }
        catch
        {
            categories = new();
        }
    }

    private async Task SearchAsync()
    {
        isLoading = true;
        errorMessage = null;

        try
        {
            var filter = new ProductFilter(
                Categories: selectedCategories.Count > 0 ? selectedCategories.ToList() : null,
                MinPrice: minPrice,
                MaxPrice: maxPrice,
                InStockOnly: inStockOnly
            );

            result = await ProductService.SearchAsync(filter, sortBy, currentPage, PageSize);
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
            result = null;
        }
        finally
        {
            isLoading = false;
        }
    }

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked)
            selectedCategories.Add(category);
        else
            selectedCategories.Remove(category);
    }

    private async Task ApplyFilters()
    {
        currentPage = 1;
        await SearchAsync();
    }

    private async Task ClearFilters()
    {
        selectedCategories.Clear();
        minPrice = null;
        maxPrice = null;
        inStockOnly = false;
        currentPage = 1;
        await SearchAsync();
    }

    private async Task OnSortChanged()
    {
        currentPage = 1;
        await SearchAsync();
    }

    private async Task GoToPage(int page)
    {
        if (page < 1 || page > TotalPages) return;
        currentPage = page;
        await SearchAsync();
    }

    private async Task OnProductSelected(Product product)
    {
        if (OnProductClicked.HasDelegate)
            await OnProductClicked.InvokeAsync(product);
    }

    private static string RenderStars(double rating)
    {
        int full = (int)Math.Round(rating);
        int empty = 5 - full;
        return new string('★', full) + new string('☆', empty);
    }
}
"}

